from django.core.cache import cache

def dashboard(request):
    key = f"dashboard:{request.user.pk}"
    data = cache.get(key)
    if data is None:
        data = build_dashboard(request.user)
        cache.set(key, data, timeout=60)
    return render(request, "dashboard.html", data)

