from django.db import transaction
from django.db.models.signals import post_save
from django.dispatch import receiver

@receiver(post_save, sender=Order, dispatch_uid="notify_paid_order")
def notify_paid_order(sender, instance, created, **kwargs):
    if instance.status == "paid":
        transaction.on_commit(lambda: send_receipt.delay(instance.pk))

# Explicit service: easier to read, test and reorder
class OrderService:
    @staticmethod
    def mark_paid(order):
        order.status = "paid"
        order.save(update_fields=["status"])
        send_receipt.delay(order.pk)
        analytics.track("order_paid", order_id=order.pk)
        return order
